pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address token, address[] memory tos, uint256 amt) public {
        vm.assume(tos.length > 0);
        // Deploy a reverter token to make sub-call fail
        Reverter reverter = new Reverter();
        // Fuzz whether the token is the reverter or something else
        address actualToken = token == address(0) ? address(reverter) : token;
        // Ensure from has approval etc. but here transfer does not check allowance
        // Call transfer and catch revert
        bool ok;
        try c.transfer(from, actualToken, tos, amt) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }
        // If the token is the reverter, the reference must revert (ok false)
        // If token is not the reverter, it might succeed; the rule is:
        // If token is the reverter, then call must NOT return true.
        // Since we cannot assert based on external callee identity without off-chain knowledge,
        // we generalize: for ANY input, the call should either revert or return true with all sub-calls having succeeded.
        // Here we enforce: if token == address(reverter) (failing callee), then ok must be false.
        // But we cannot distinguish token identity in assertion without binding; we want a general rule:
        // The transfer call should NOT return true if it made any sub-call that failed.
        // To encode this as a general property requiring adversarial counterparty, we route through the reverter.
        assertTrue(!ok || actualToken != address(reverter));
    }
}
