        bool ok;
        try c.transfer(address(this), address(reverter), tos, v) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }
        // Property: the call must revert (ok == false). Buggy version returns true and does not revert.
        assertTrue(!ok, "Expected revert but call succeeded");
    }
}

