pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 1);
        vm.assume(from != address(this) && caddress != address(this));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0) && _tos[i] != address(this) && _tos[i] != caddress && _tos[i] != from);
        }
        // Use a helper that always returns success on low-level call, because the reference makes multiple external calls.
        // Deploy a simple contract that succeeds on any call to simulate a token-like behavior.
        Helper helper = new Helper();
        // Drive through the actual transfer call
        vm.prank(from);
        bool result = c.transfer(from, address(helper), _tos, v);
        // The reference returns true after processing the entire array; the bug still returns true but stops early.
        // We need to check that all calls were made. To observe this, we query the helper for call counts.
        // The helper records the number of calls made to it.
        // Since the bug returns after the first call, the call count will be 1 for the bug, and _tos.length for reference.
        // The invariant: the number of external calls to the target must equal _tos.length.
        // We assert that the helper's call count equals the length of _tos.
        assertEq(helper.callCount(), _tos.length);
    }
}

contract Helper {
    uint256 public callCount;
    fallback() external payable {
        callCount++;
    }
}

