pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // The external call inside c must succeed, so fuzz a caddress that is an EOA (or a helper that succeeds).
        // Low-level call to an EOA always succeeds; we don't need an adversarial helper here because the
        // difference is the unconditional revert in M, not a failing external callee.
        // Fuzzer may still supply a contract address; we ensure success by deploying a trivial helper that accepts calls.
        // Since the spec says the fuzzer cannot synthesize code from raw address, we deploy a trivial success helper.
        SuccessHelper helper = new SuccessHelper();
        // Use helper when fuzzed caddress would otherwise be a raw address requiring code for the call to have predictable behavior.
        // The actual fuzzed caddress is replaced with helper for the call to succeed.
        address target = address(helper);
        bool ok = false;
        try c.transfer(from, target, _tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract SuccessHelper {
    fallback() external payable {}
}
